"""Author finite documentary cases. This generates no Live files and executes no reference."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
cases=[]
def add(prefix, number, requirement, kinds, setup, action, expected, comparator, source, grade='D12'):
    cases.append(dict(id=f'{prefix}-{number:03}',requirement=requirement,kinds=kinds.split(','),setup=setup,action=action,expected=expected,comparator=comparator,documentary_grade=grade,target_build_grade='U',execution='unexecuted',source=source))
def m(n,k,s,a,e,c,src):
    add('MPE',n,f'REQ-MPE-{n:03}',k,s,a,e,c,src)
m(1,'positive,negative','Controller selected as MIDI input; individually selectable input channel.','Enable controller MPE mode.','Track input is All Channels; individual channel selection unavailable.','Compare selected channel and allowed channel choices; incoming MIDI handling outside this case.','M1')
m(2,'positive','MIDI clip with notes made without MPE hardware; Note Expression closed.','Open Note Expression with tab or Alt/Option+3.','Pitch overlay and Slide/Pressure/Velocity/Release Velocity controls accessible; Slide/Pressure default-visible.','Compare dimension names and visibility in an uncustomized view; optional Pitch lane U.','M1,M2')
m(3,'positive,boundary','No expression lanes enabled.','Click triangle, then hide; Alt/Option-click triangle; resize one lane then total split.','All lanes shown from empty state; visibility toggles hide with lanes; resizing affects selected lane or total group.','Compare visible selectors and relative lane sizes; no pixel/minimum-size assertion.','M2')
m(4,'positive','Two notes with distinct Pressure envelopes.','Select first note then its Pressure envelope.','First note/curve editable and highlighted; second dimmed; background drag defines selection.','Compare selected-note identity and editable breakpoint set.','M3')
m(5,'positive','Pressure envelope has points at local beats 0.25 and 0.75 with values 20 and 40.','Click middle segment, delete added point by click; choose Edit Value on first and enter 30.','One point added then removed; edited point displays 30.','Compare point count changes +1/-1 and final entered value; numeric rounding beyond these integers U.','M3')
m(6,'positive','One note, interior Pressure points at 0.25/0.5/0.75; middle time region selected.','Drag middle segment vertically; Shift-drag a selected point horizontally.','Segment region gets edge breakpoints and moves together; Shift restricts axis.','Compare edge-point presence and unchanged perpendicular coordinates; drag thresholds/clipping U.','M3')
m(7,'positive,persistence','Note Expression grid off, Notes-tab grid on.','Toggle Expression grid on; switch tabs; save/reopen clip.','Expression grid independent of other tab and saved with clip.','Compare per-tab enabled state and reopened Expression-grid state; full clip save errors U.','M3')
m(8,'positive','Straight interior Pressure segment.','Alt/Option-drag segment then Alt/Option-double-click.','Curve becomes curved, then straight.','Compare curve/straight visual state only; numerical sample interpolation U.','M3')
m(9,'positive,negative','Nonzero non-Pitch envelope with several selected points, values away from limits.','Scale via outside-note hover gesture; separately select all points and move vertically.','First adjusts proportionally; second moves all chosen values equally; Pitch lacks proportional gesture.','Compare relative versus equal movement of nonzero values; scale amount/origin and clipping U.','M3')
m(10,'positive','Note starts at beat 1, duration 2; expression local points 0.5 and 1.5.','Move note start to beat 3; separately stretch duration by x2.','Move carries expression +2 beats in clip time; stretch carries expression timing with doubled note.','Compare +2 absolute time translation; stretch corresponding interior times 1 and 3 relative to new note start; exact endpoints U.','M3')
m(11,'positive,boundary','Unfolded Note Expression with grid off and bend above note.','Modifier-edit bend near an unambiguous semitone; invoke Zoom to Clip Selection.','Pitch snaps to nearest semitone; zoom includes selected bends.','Compare displayed semitone and visible selected bend extent; half-semitone tie and folded lane state U.','M3')
m(12,'positive','Two selected notes with Pressure and Slide, third unselected.','Choose Clear All Envelopes in Note Expression.','Selected notes expression envelopes clear.','Compare absence of selected curves; velocity/default reset and unselected-state guarantee U.','M3')
m(13,'positive,boundary','Note Expression Pitch/Pressure/Slide target and visible one-quarter-beat grid.','Turn Draw Mode on, draw over interior region; repeat holding B temporarily.','Grid drawing creates steps at visible grid width; holding B temporarily toggles Draw Mode.','Compare step horizontal widths 0.25 beat and restored mode on release; point samples/endpoints U.','M4')
m(14,'positive,persistence','MPE-enabled plugin with MIDI out and saved default configuration.','Save its enabled MPE default; create instance from default.','MPE enable state recalled; MPE output supported when enabled.','Compare default-enabled flag; exact emitted messages and blue-meter timing U.','M2,M5')
m(15,'positive','External Instrument or MIDI track with valid MIDI To target; MPE-enabled plugin instance.','Choose MPE then MPE Settings in each output route; open plugin context entry.','Settings dialog accessible through three documented entry points.','Compare dialog presence/associated target in each location; commit/cancel U.','M6')
m(16,'positive,negative,boundary','Two tracks share an external output; no sounding notes.','Configure one lower zone, one upper; inspect single-track zone choices.','Lower global channel 1; upper global channel 16; each track one zone.','Compare configured labels/global channels and inability to select both zones as one track configuration; message allocation U.','M7')
m(17,'positive','MPE output settings with no sounding notes.','Select multi-channel mode and choose note-channel range 3..8.','Configuration exposes chosen arbitrary note-channel range.','Compare displayed endpoints 3 and 8; emitted ordering, upper/lower limits and global-channel exclusion U.','M7')
m(18,'positive,negative','Controller and compatible MPE instrument, both with known bend-range setting.','Set matching ranges; separately mismatch them.','Matching range is required configuration for correct tracking; mismatch cannot be graded to a precise sound.','Compare matched setup values only; output pitch curve, failure size, default and codec remain U.','H1')

def t(n,k,s,a,e,c,src):
    add('TUN',n,f'REQ-TUNING-{n:03}',k,s,a,e,c,src)
t(1,'positive','No tuning loaded; valid user ASCL located in browser Places.','Browse Tunings/User; hover file.','User file discoverable; Info View contains tuning description/note count.','Compare listed file and known description/count; indexing delay U.','T1')
t(2,'positive,persistence','Browser Tuning section hidden; valid shipped tuning.','Load by double-click then, reset, Enter; save/reopen Set.','Tuning section opens and loaded tuning retained in Set.','Compare tuning identity across methods and reopen; bitwise serialization U.','T2')
t(3,'positive','Loaded tuning with documented degree name and reference.','Hover tuning note in piano roll and audition.','Status Bar reports pitch/frequency corresponding to displayed tuning note.','Compare known degree label; audio and arbitrary frequency equation/tolerance U.','T2')
t(4,'positive,negative','Clip has note indices 60 and 64; Retune Set disabled.','Change tuning then remove.','Indices 60/64 retained; no destructive-retune confirmation; ruler labels can change.','Compare indices exactly and confirmation absence; frequencies U.','T2,H2')
t(5,'positive','Existing melody; Retune Set enabled and a distinct valid tuning selected.','Load new tuning.','Retune confirmation shown before destructive retuning.','Compare confirmation presence; closest-pitch arithmetic/tie/collision survivor and actual note output U.','T2,H2')
t(6,'positive,negative','Scale Mode visible and scale-aware device Use Current Scale on.','Load retained 12-TET ASCL.','Scale choosers hidden; device Use Current Scale unavailable.','Compare visibility/enabled state even though loaded file describes 12TET; preserved hidden state U.','T2,H3')
t(7,'positive','Loaded tuning; reference display captured; stable compatible sustained test note.','Change reference Octave/Note identity without directly editing frequency.','Displayed reference frequency updates while sounding pitch does not change.','Compare before/after pitch equality under identity-only edit; exact new displayed number and measured tolerance U.','T3')
t(8,'positive','Loaded tuning with reference 440Hz in compatible setup.','Edit Ref. Pitch/Freq to 432Hz.','Reference control reads 432Hz and note pitches lower.','Compare numeric reference value and direction only; absolute frequencies, settling time and held-note policy U.','T3,H3')
t(9,'positive,boundary','Tuning range with N intervening indices captured.','Change Lowest Note by one tuning position, then separately Highest Note.','Other endpoint updates keeping N intervening positions.','Compare index-count invariant, avoiding limits; frequency monotonicity U.','T3')
t(10,'positive,negative','Loaded tuning edited to reference 432Hz; separate tuning without LINK.','Save tuning via disk button; inspect arrow for unlinked tuning.','ASCL output has current tuning; no-link arrow disabled.','Compare saved tuning/reference metadata and disabled arrow; save dialog path/overwrite/error U.','T3,A5')
t(11,'positive','Loaded tuning selected; Retune Set off.','Press Delete.','Default 12TET restored, existing note indices retained.','Compare loaded tuning absence and unchanged indices; previously heard pitch need not be restored.','T2,T3,H2')
t(12,'positive','Loaded non-12TET tuning; two MIDI tracks, one with Drum Rack.','Enable Bypass on other track.','Bypassed track displays 12TET and passes original MIDI; Drum Rack track automatically bypasses.','Compare bypass state/ruler and input/output note-number identity at documented abstraction; exact MIDI bytes U.','T4,H2')
t(13,'positive','Loaded tuning and external keyboard input.','Choose Black Keys Only then White Keys Only.','Layout choices center at C#3 and C3 respectively.','Compare selected mapping mode and center labels; full note table and boundary keys U.','T5')
t(14,'positive,persistence','Custom layout editable for a MIDI track.','Choose Custom, open ellipsis, make one valid mapping edit; save/reopen Set.','Custom dialog opens and mapping is recalled.','Compare edited mapping state before/after reopen; exact valid domain and duplicate mapping U.','T5')
t(15,'positive,negative','External MPE-capable receiver or plugin with documented bend setting.','Enable MPE and set per-note bend range ±48.','Configured prerequisites for tuning receiver met.','Compare capability/enable and range settings; arbitrary receiver sound and Live auto-negotiation U.','T1,H3')
t(16,'positive,negative','Valid SCL has intervals but no reference; optional KBM available.','Load SCL; separately attempt KBM selection.','Live supplies 440Hz reference near middle of MIDI range; KBM unsupported.','Compare reference frequency 440Hz and documented unsupported classification only; generated note index and KBM UI U.','H3')
t(17,'negative,malformed','Valid SCL pitch list followed by Ableton directive with deliberately non-UTF-8 byte in a name.','Import through extension parser.','Non-UTF-8 extension input is rejected by documented compliant-parser rule.','Compare rejection rather than accepted extended tuning; dialog/recovery state U.','A1')
t(18,'positive,boundary','Valid 12-entry ASCL, REFERENCE_PITCH 3 9 440.0 and twelve NOTE_NAMES.','Import.','Reference fields describe octave 3 degree 9 at 440Hz; name list begins at degree zero.','Compare reference identity/frequency and degree-zero name; extra directives and parser normalization U.','A2')
t(19,'negative,malformed','Valid ASCL with both NOTE_RANGE_BY_INDEX and NOTE_RANGE_BY_FREQUENCY directives.','Import.','Multiple range directives are an error.','Compare presence of range-validation error; transaction recovery/error text and refusal stage U.','A3')
t(20,'positive,boundary','Valid 12-note ASCL without range; reference suitable for unambiguous nearest A3.','Import.','Note closest to A3 440Hz placed at tuning index 69 in twelve-note special case.','Compare nearest-note/index relationship; ties and arbitrary explicit-reference recentering U.','A4')
t(21,'positive','Valid nonmonotonic tuning with earlier REFERENCE_PITCH, explicit index range, SOURCE/LINK.','Import and inspect order/range labels/metadata.','Index range means first/last positions rather than sorted frequency extrema; origin/link represented.','Compare preserved degree order/range positions and metadata; software may restrict clickable URL.','A3,A5')

def g(n,k,s,a,e,c,src,grade='D12'):
    add('GRV',n,f'REQ-GROOVE-{n:03}',k,s,a,e,c,src,grade)
g(1,'positive','Valid AGR and two distinct editable MIDI clips; empty pool.','Double-click AGR; then drag onto first clip.','Groove appears in pool inactive then becomes assigned to first clip.','Compare pool presence, inactive visual state and clip assignment; duplicate import U.','G1,G2')
g(2,'positive,negative','Audio clip A Warp on and reset copy B Warp off.','Assign same groove.','A supports groove through Warp; B has no supported effect without Warp.','Compare prerequisites/assignment availability; exact auto-enable/refusal UI and audio output U.','G1')
g(3,'positive','Pool hidden; two clips assigned same groove.','Use shortcut/view toggle; change Timing while playing.','Pool shows/hides; shared groove setting influences using clips.','Compare pool visibility and shared setting identity; actual timing/update latency U.','G2')
g(4,'positive,boundary','Groove events exactly at 0/0.5 beat, Base 1/8; clip notes at same positions; Quantize/Random/Velocity zero.','Apply Timing 100%.','Grid-aligned groove contributes no timing displacement to corresponding notes.','Compare clip note times unchanged for these exact aligned inputs; correspondence outside this setup U.','G3')
g(5,'positive,boundary','Clip starts 0.1/0.6 beats; Base 1/8; Timing/Random/Velocity zero.','Set Quantize 100%, then reset and 0%.','Straight-stage positions 0/0.5 at 100%; original 0.1/0.6 at 0%.','Compare documented straight quantization endpoints, away from ties; sample emission U.','G3')
g(6,'positive,negative','Off-grid groove, clip starts captured; Quantize/Random/Velocity zero.','Set Timing zero.','No groove-pattern timing displacement.','Compare represented/playback event times equal originals under zero active influences; engine samples U.','G3,G6')
g(7,'positive,boundary','Chord contains two simultaneous voices; Random nonzero, other influences zero.','Play repeated loops; retain each voice onset.','Documented random influence may separate voices; no fixed stream, distribution or guaranteed distinct realization.','U: no documented statistical threshold, numeric bound or complete random oracle; do not grade one coincident outcome as failure.','G3','U')
g(8,'positive,boundary','Groove with alternating quieter/louder velocities; clip with otherwise uniform notes.','Compare Velocity +100%, 0%, -100%.','Control accepts documented endpoints; zero removes velocity influence; negative reverses emphasis.','Compare allowed endpoints, no influence at zero, qualitative emphasis reversal only; exact velocity values U.','G3,G6')
g(9,'positive,boundary','Grooves assigned; settings captured and Quantize nonzero.','Set Global Amount 100% then 130%.','100% uses assigned intensities; 130% endpoint available; control-bar slider visible.','Compare allowed values/control visibility; precise composite effect and Quantize-scaling outcome U.','G3')
g(10,'positive','Separate MIDI and Warp-enabled audio clip with assigned groove.','Commit each.','MIDI notes receive movement, audio receives appropriate Warp Markers; each assignment becomes None.','Compare assignment reset and marker/note edit presence with nonzero timing setup; exact content/random sample U.','G4')
g(11,'positive','Valid groove in browser/pool and empty MIDI destination.','Drag groove to MIDI track; edit resulting clip.','New editable MIDI clip contains groove material.','Compare clip creation and editable notes, without asserting unknown conversion defaults.','G5')
g(12,'positive','Clip has distinct material inside playing region and outside it.','Extract via context menu and separately drag into pool.','New groove created considering playing portion only.','Compare creation by both routes; exact event/volume detector and endpoint inclusion U.','G5')
g(13,'positive,negative','Two different groove files; identical notes 0.1/0.6; Base 1/8, Quantize100, Timing/Random/Velocity0.','Apply without Commit and compare.','Both produce same straight quantization 0/0.5; source clip data unchanged before commit.','Compare equal scheduled positions at documentary event abstraction and unchanged original note starts; sample schedule U.','G6')
g(14,'positive','Playing clip with assigned groove; valid alternate grooves.','Enable clip Groove Hot-Swap and choose alternatives; inspect pool save control.','Groove selection can change while playback continues; pool save/hot-swap available.','Compare assigned groove identities and controls; disruption-free/sample-continuous switching U.','G1,G2')

