for prefix, entries in unknowns.items():
    start={'MPE':19,'TUN':22,'GRV':15}[prefix]
    for offset,(k,req,s,a,e,src) in enumerate(entries):
        add(prefix,start+offset,req,k,s,a,e,'U: retain observations for a future evidenced contract; no pass/fail oracle is asserted.',src,'U')
assert len(cases)==83
assert len({x['id'] for x in cases})==83
for prefix,total in [('MPE',27),('TUN',32),('GRV',24)]:
    assert sum(x['id'].startswith(prefix) for x in cases)==total
(ROOT/'cases.json').write_text(json.dumps(cases,indent=2)+'\n')
counts={p:{g:sum(x['id'].startswith(p) and x['documentary_grade']==g for x in cases) for g in ['D12','U']} for p in ['MPE','TUN','GRV']}
(ROOT/'case-counts.json').write_text(json.dumps(counts,indent=2)+'\n')
print(json.dumps(counts))
